input.command:
cd /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/record-rule && sed -i "s/Whether POSITIONS' pointer is worth its length is still your call, from the pairs\./Whether POSITIONS' pointer is worth its length is still your call, as the pairs in the trial ask./" page.html && cat > check400.cjs <<'EOF'
const { chromium } = require('/opt/node-tools/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
  for (const scheme of ['light','dark']) {
    const p = await b.newPage({ viewport: { width: 400, height: 900 }, colorScheme: scheme });
    await p.goto('file://' + process.cwd() + '/page.html');
    await p.waitForTimeout(500);
    const r = await p.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const out = [];
      document.querySelectorAll('body *').forEach(el => {
        const rc = el.getBoundingClientRect();
        if (rc.width > 0 && (rc.right > vw + 0.5 || rc.left < -0.5)) {
          let anc = el.closest('details:not([open])'); if (anc) return;
          out.push(el.tagName + '.' + el.className + ' ' + Math.round(rc.left) + '-' + Math.round(rc.right) + ' ' + (el.textContent||'').slice(0,60));
        }
      });
      return { scroll: document.documentElement.scrollWidth, client: vw, over: out.slice(0,20), n: out.length };
    });
    console.log(scheme, JSON.stringify(r, null, 1));
    if (scheme === 'light') {
      await p.screenshot({ path: 'shot-principles-top.png' });
      const el = await p.$('#h-rule'); await el.scrollIntoViewIfNeeded();
      await p.screenshot({ path: 'shot-rule.png' });
    } else {
      await p.screenshot({ path: 'shot-principles-dark.png' });
    }
  }
  await b.close();
})();
EOF
node check400.cjs

